import type {
  CompanyConfig,
  CompanyNarrative,
  CompanyNarrativeArc,
  CompanyPersonalityArchetype,
  CompanyTraits,
  IndustryThemeKey,
  RegionKey,
  TraitKey,
} from "../types";

interface CompanySeed {
  id: string; name: string; ticker: string; logoStyle: string; tagline: string; headquarters: string;
  industry: IndustryThemeKey; region: RegionKey; archetype: string; commodity: string;
  role: string; personality: CompanyPersonalityArchetype; price: number; volatility: number;
  belief: string; desire: string; strength: string; flaw: string; fear: string; culture: string;
  excitement: string; hesitation: string; catalyst: string; unknown: string;
  hiddenTruth: string; secretOpportunity: string; secretWeakness: string; moralDilemma: string;
  ambition: string; founder: string; story: string; chapter: string; decisionQuestion: string;
  rival: [string, string]; ally: [string, string]; macroPressure: string;
  traitOverrides: Partial<CompanyTraits>; visible: TraitKey[];
}

const baseTraits: CompanyTraits = {
  builderDna: 5, geologicalLuck: 5, balanceSheet: 5, managementQuality: 5, infrastructure: 5,
  politicalRisk: 5, marketHype: 5, commodityExposure: 5, optionality: 5, executionSkill: 5,
};

const arc = (id: string, title: string, premise: string, tags: string[], beats: string[], question: string): CompanyNarrativeArc => ({
  id, title, premise, triggerTags: tags, beats, unresolvedQuestion: question,
});

function arcs(seed: CompanySeed) {
  const prefix = seed.id;
  return {
    growth: [
      arc(`${prefix}-growth-proof`, "Proof Becomes Scale", seed.catalyst, ["growth", "execution"], ["A small proof survives.", "Demand arrives before capacity.", "Culture is tested by speed."], `Can ${seed.name} grow without sacrificing ${seed.strength.toLowerCase()}?`),
      arc(`${prefix}-growth-price`, "The Price of Becoming Visible", seed.ambition, ["growth", "hype"], ["The market notices.", "Capital becomes easy.", "An expansion tempts the company beyond its discipline."], `Does attention strengthen the mission or awaken ${seed.flaw.toLowerCase()}?`),
    ],
    crisis: [
      arc(`${prefix}-crisis-flaw`, "The Flaw Takes Control", seed.flaw, ["crisis", "identity"], ["A warning is dismissed.", "The hidden cost becomes public.", "Leadership must admit what it protected."], `Can the company survive the weakness created by its own identity?`),
      arc(`${prefix}-crisis-truth`, "The Buried Truth", seed.hiddenTruth, ["crisis", "secret"], ["A contradiction appears.", "Insiders choose silence or disclosure.", "Trust becomes more valuable than the original plan."], seed.decisionQuestion),
    ],
    leadership: [
      arc(`${prefix}-leadership-founder`, "The Founder’s Shadow", seed.founder, ["leadership", "founder"], ["The founder’s old promise returns.", "A successor challenges it.", "The company chooses legacy or adaptation."], `Can the mission survive the person who created it?`),
      arc(`${prefix}-leadership-culture`, "Culture Under Pressure", seed.culture, ["leadership", "culture"], ["Rapid change divides the team.", "A valued operator leaves.", "The board learns what the culture actually rewards."], `What remains when stated values become expensive?`),
    ],
    technology: [
      arc(`${prefix}-technology-breakthrough`, "The Difficult Proof", seed.catalyst, ["technology", "proof"], ["A prototype works.", "Real conditions expose a weakness.", "The team chooses reliability or speed."], `Is technical success enough to create a durable organization?`),
      arc(`${prefix}-technology-debt`, "The Shortcut Comes Due", seed.secretWeakness, ["technology", "execution"], ["A hidden compromise surfaces.", "Customers demand repair.", "Growth pauses while credibility is rebuilt."], `Will the company repair the foundation or keep selling the future?`),
    ],
    competition: [
      arc(`${prefix}-competition-rival`, "The Rival Moves First", `${seed.rival[0]} attacks the assumption protecting ${seed.name}.`, ["competition", "rival"], ["The rival wins a visible customer.", "The market declares a winner too early.", "A neglected strength becomes relevant."], `Does ${seed.name} imitate its rival or become more itself?`),
      arc(`${prefix}-competition-ally`, "The Alliance With Conditions", seed.ally[1], ["competition", "ally"], ["Cooperation creates leverage.", "Value becomes visible.", "Control threatens the partnership."], `Can mutual dependence survive success?`),
    ],
    macro: [
      arc(`${prefix}-macro-tailwind`, "The World Finally Agrees", seed.macroPressure, ["macro", "tailwind"], ["Demand changes.", "Investors arrive.", "Weak execution hides inside a strong cycle."], `Is the company creating value—or merely receiving weather?`),
      arc(`${prefix}-macro-reversal`, "The Tide Leaves", `The world moves against ${seed.belief.toLowerCase()}`, ["macro", "reversal"], ["Financing tightens.", "Customers delay.", "Only the original character remains."], `Was the thesis durable without a favorable world?`),
    ],
    reputation: [
      arc(`${prefix}-reputation-earned`, "Trust Compounds", seed.strength, ["reputation", "trust"], ["A promise is kept.", "Institutions remember.", "A private opportunity arrives first."], `What will the company do with trust it no longer has to beg for?`),
      arc(`${prefix}-reputation-broken`, "The Story Stops Working", seed.hesitation, ["reputation", "failure"], ["Guidance is missed.", "Old defenders go quiet.", "New evidence must replace charisma."], `Can a company repair trust without changing its identity?`),
    ],
    unexpected: [
      arc(`${prefix}-unexpected-truth`, "The Company Inside the Company", seed.hiddenTruth, ["unexpected", "hidden-truth"], ["An overlooked detail becomes material.", "The original valuation stops making sense.", "The player must reinterpret every earlier choice."], `What else was hidden by the first story?`),
      arc(`${prefix}-unexpected-fear`, "The Thing It Feared", seed.fear, ["unexpected", "fear"], ["The feared outcome begins.", "Preparation proves incomplete.", "A strange alternative becomes possible."], `Can fear become information instead of destiny?`),
    ],
    opportunity: [
      arc(`${prefix}-opportunity-secret`, "The Unopened Door", seed.secretOpportunity, ["opportunity", "secret"], ["A private signal appears.", "Entering requires sacrifice.", "The company risks becoming something new."], seed.moralDilemma),
      arc(`${prefix}-opportunity-sacrifice`, "The Opportunity That Costs Identity", seed.ambition, ["opportunity", "tradeoff"], ["A powerful partner arrives.", "The terms solve the immediate problem.", "The original mission becomes negotiable."], `How much identity should be exchanged for survival or scale?`),
    ],
  } satisfies CompanyNarrative["arcCategories"];
}

function buildNarrative(seed: CompanySeed): CompanyNarrative {
  const arcCategories = arcs(seed);
  return {
    frameworkVersion: 2,
    identity: seed.role,
    personalityArchetype: seed.personality,
    belief: seed.belief,
    coreDesire: seed.desire,
    greatestStrength: seed.strength,
    fatalFlaw: seed.flaw,
    companyCulture: seed.culture,
    investorExcitement: seed.excitement,
    investorHesitation: seed.hesitation,
    biggestCatalyst: seed.catalyst,
    biggestUnknown: seed.unknown,
    hiddenTruth: seed.hiddenTruth,
    secretOpportunity: seed.secretOpportunity,
    secretWeakness: seed.secretWeakness,
    moralDilemma: seed.moralDilemma,
    longTermAmbition: seed.ambition,
    fear: seed.fear,
    founderStory: seed.founder,
    currentChapter: seed.chapter,
    futurePossibilities: [
      `It achieves ${seed.ambition.toLowerCase()}`,
      `It survives by confronting ${seed.flaw.toLowerCase()}`,
      `It is transformed by ${seed.secretOpportunity.toLowerCase()}`,
    ],
    rivals: [{ companyId: seed.rival[0], relationship: "Defining competitor", tension: seed.rival[1] }],
    allies: [{ companyId: seed.ally[0], relationship: "Conditional ally", tension: seed.ally[1] }],
    stakeholders: [
      { name: `${seed.headquarters.split(",")[0]} Authority`, role: "regulator", leverage: "Controls the permission or infrastructure the current chapter requires.", tension: seed.moralDilemma },
      { name: `${seed.name} Founding Circle`, role: "founder", leverage: "Protects the original mission.", tension: seed.fear },
    ],
    relationshipHooks: [`Let ${seed.rival[0]} exploit ${seed.flaw.toLowerCase()}`, `Let ${seed.ally[0]} unlock ${seed.secretOpportunity.toLowerCase()}`, "Remember whether the player protected conviction or rewarded the easiest story."],
    narrativeVariables: [
      { id: `${seed.id}-macro-variable`, variable: seed.macroPressure, condition: "The macro pressure intensifies.", consequence: `It amplifies both ${seed.strength.toLowerCase()} and ${seed.flaw.toLowerCase()}`, affectedRelationships: [seed.rival[0], seed.ally[0]] },
      { id: `${seed.id}-player-variable`, variable: "player behavior", condition: "The player repeatedly funds, ignores, researches, or abandons the company.", consequence: "Future access, trust, and endings remember that pattern.", affectedRelationships: [seed.id] },
    ],
    macroTriggers: [{ id: `${seed.id}-macro`, when: seed.macroPressure, storyBeat: `The world tests whether ${seed.belief.toLowerCase()}`, tags: [seed.industry, "macro"] }],
    crisisArcs: arcCategories.crisis ?? [],
    comebackArcs: [arcCategories.growth?.[0], arcCategories.reputation?.[0]].filter((item): item is CompanyNarrativeArc => Boolean(item)),
    legendaryEndings: [{ id: `${seed.id}-legendary`, title: seed.ambition, legend: `${seed.name} becomes proof that ${seed.belief.toLowerCase()}`, condition: `Survive three identity-testing crises, preserve ${seed.strength.toLowerCase()}, and complete the central ambition.` }],
    hiddenEndings: [{ id: `${seed.id}-hidden`, title: "The Future Nobody Underwrote", legend: seed.secretOpportunity, condition: `Reveal the hidden truth, resolve the moral dilemma against short-term advantage, and preserve the key alliance.` }],
    eventTriggers: [
      { id: `${seed.id}-rival-trigger`, when: `${seed.rival[0]} experiences a major event.`, storyBeat: `${seed.name} gains or loses room to act.`, tags: ["relationship", "rival"] },
      { id: `${seed.id}-memory-trigger`, when: "The company returns in a later run.", storyBeat: "It references how the player treated it before.", tags: ["memory", "relationship"] },
    ],
    arcCategories,
  };
}

function buildCompany(seed: CompanySeed): CompanyConfig {
  return {
    id: seed.id, name: seed.name, ticker: seed.ticker, logoStyle: seed.logoStyle, tagline: seed.tagline,
    headquarters: seed.headquarters, industry: seed.industry, region: seed.region, archetype: seed.archetype,
    commodity: seed.commodity, basePrice: seed.price, volatility: seed.volatility, role: seed.role,
    desire: `Wants to ${seed.desire.charAt(0).toLowerCase()}${seed.desire.slice(1)}`,
    flaw: seed.flaw, story: seed.story, decisionQuestion: seed.decisionQuestion,
    narrative: buildNarrative(seed), traits: { ...baseTraits, ...seed.traitOverrides }, initiallyVisible: seed.visible,
  };
}

